head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods10010";
scwin.result = null;
scwin.checkIdAjax = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — sType, sMessage

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "img_12", attr: "src", fn: function () { return String(String((dma_pageContext.get("logoImg") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.checkResult();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.checkIdAjax = scwin.tx_checkIdAjax;
        scwin.init_recvParam();
        scwin.init_attrReals();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods10010.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name a_11_onclick
 * @description a_11 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.a_11_onclick = function(e){
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10010.a_11_onclick' }); }
};

/**
 * @method
 * @name ipt_bPw_onkeydown
 * @description 「현재 비밀번호」 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_bPw_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.ctrlKey){ await alertE("컨트롤 키를 사용할 수 없습니다."); return false;}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.ipt_bPw_onkeydown' }); }
};

/**
 * @method
 * @name chkBtn_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkBtn_onclick = async function(e){
    try {
        await scwin.checkIsBeforePW('A',$c.util.getComponent('ipt_bPw').getValue())

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.chkBtn_onclick' }); }
};

/**
 * @method
 * @name ipt_pw_onkeydown
 * @description 「새비밀번호」 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_pw_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.ctrlKey){ await alertE("컨트롤 키를 사용할 수 없습니다."); return false;}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.ipt_pw_onkeydown' }); }
};

/**
 * @method
 * @name ipt_pwChk_onkeydown
 * @description 「새비밀번호확인」 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_pwChk_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.ctrlKey){ await alertE("컨트롤 키를 사용할 수 없습니다."); return false;}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.ipt_pwChk_onkeydown' }); }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.btn_Save_onclick' }); }
};

/**
 * @method
 * @name btn_restartTimer_onclick
 * @description 「연장하기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_restartTimer_onclick = async function(e){
    try {
        await $c.session.sessionCheck()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10010.btn_restartTimer_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Save
 * @description Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Save = async function () {
    const sbmOptions = {
        id: "tx_fn_Save",
        method: "post",
        action: "/main/pwChg.do?method=updatePassword",
        ref: "dma_SaveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_checkIdAjax
 * @description check Id Ajax 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_checkIdAjax = async function () {
    const sbmOptions = {
        id: "tx_checkIdAjax",
        method: "post",
        action: "/main/login.do",
        ref: "dma_checkIdAjaxReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_checkSafety
 * @description check Safety 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_checkSafety = async function () {
    const sbmOptions = {
        id: "tx_checkSafety",
        method: "post",
        action: "/common/checkSafety.do",
        ref: "dma_checkSafetyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkResult
 * @description check Result 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkResult = async function () {
    const tp = (String(((dma_pageContext.get("sType") ?? "")) === null ? '' : ((dma_pageContext.get("sType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sType") ?? "")) === null ? '' : ((dma_pageContext.get("sType") ?? ""))));
    if (tp === '1') {
        await alertE('비밀번호 변경이 완료되었습니다.\n다시 로그인하시기 바랍니다.', function() {
                $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil45000/jldfil45000.xml');
        });
    } else {
        if (tp === '2') {
            await alertE((String(((dma_pageContext.get("sMessage") ?? "")) === null ? '' : ((dma_pageContext.get("sMessage") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sMessage") ?? "")) === null ? '' : ((dma_pageContext.get("sMessage") ?? "")))));
        }
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    const frm = (document.passwordForm || { elements: [] });
    if ($c.util.getComponent('ipt_bPwYn').getValue() !== "Y") {
        await alertE("현재 비밀번호를 확인하시기 바랍니다.");
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_bPw'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_pw'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_pwChk'))) {
        return;
    }
    if ($c.util.getComponent('ipt_pw').getValue()!== $c.util.getComponent('ipt_pwChk').getValue()) {
        await alertE('입력한 새 비밀번호가 일치하지 않습니다. 새 비밀번호를 확인하십시오.');
        return;
    }
    if (!await scwin.checkPassword($c.util.getComponent('ipt_pw').getValue())) {
        pw.focus();
        return;
    }
    if ($c.util.getComponent('ipt_isPass').getValue() !== "Y") {
        await alertE("입력하신 비밀번호 보안등급이 낮습니다. \n다시 입력하여 주시기 바랍니다.");
        return;
    }
    if ($c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'Y') {
        $c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'N';
    }
    confirmF("비밀번호를 변경하시겠습니까?", async function() {
            frm.action = '/main/pwChg.do?method=updatePassword';
            await scwin.tx_fn_Save();
    });
};

/**
 * @method
 * @name checkPassword
 * @description check Password 처리
 * @param {*} _password _password
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPassword = async function (_password) {
    const pwVal = _password;
    if (pwVal.length < 9) {
        await alertE("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        return false;
    }
    const strChk = /^[\a-z0-9_!@#^&*()]{8,}$/;
    if (!(strChk.test(pwVal.toLowerCase()))) {
        await alertE("변경 비밀번호는 한글,띄어쓰기는 사용하실 수 없습니다.\n_!@#^&*() 이외의 특수문자는 사용하실 수 없습니다.");
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const sChar_t = "_!@#^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let numberCheck_t = false;
    for (let i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) !== -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) !== -1) {
            alphaCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) !== -1) {
            numberCheck_t = true;
        }
    }
    if (sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) {
        await alertE("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        return false;
    }
    let sameCount = 1;
    let isCont = true;
    for (let i = 0; i < pwVal.length - 1; i++) {
        const currentChar = pwVal.charAt(i);
        const nextChar = pwVal.charAt(i + 1);
        const currentCharNum = parseInt(currentChar.charCodeAt(0));
        const continueCharNum = parseInt(nextChar.charCodeAt(0));
        if (currentChar === nextChar) {
            sameCount = sameCount + 1;
            if (sameCount >= 3) {
                break;
            }
        } else {
            sameCount = 1;
        }
        if (!(isCont && currentCharNum === continueCharNum - 1)) {
            isCont = false;
        }
    }
    if (sameCount >= 3) {
        await alertE('동일한 문자 또는 숫자가 3자 이상로 구성된 비밀번호는 사용할 수 없습니다.');
        return false;
    }
    if (isCont) {
        await alertE('주기성 문자(abcd, 1234 등)로 구성된 비밀번호는 사용할 수 없습니다.');
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await alertE('변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.');
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (let i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length === 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await alertE('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용할 수 없습니다.');
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name fnDelayKeyup
 * @description fn Delay Keyup 처리
 * @param {*} newPw newPw
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDelayKeyup = async function (newPw) {
    if (newPw.length > 0) {
        if (await scwin.checkPassword(newPw)) {
            await scwin.checkIsBeforePW("B", newPw);
        }
    }
};

/**
 * @method
 * @name checkIsBeforePW
 * @description check Is Before PW 처리
 * @param {String} gbCd gbCd
 * @param {*} pw pw
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIsBeforePW = async function (gbCd, pw) {
    if (pw.length > 0) {
        scwin.checkIdAjax(gbCd, pw);
    } else {
        if (gbCd === "A") {
            await alertE("현재 비밀번호를 입력하시기 바랍니다");
        }
    }
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkSafety_done
 * @description check Safety done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSafety_done = async function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_isPass').setValue(scwin.result.isPass);
    $c.util.getComponent('ipt_selfLevel').setValue(scwin.result.selfLevel);
    $c.util.getComponent('txt_msgLevel').setLabel(scwin.result.msgLevel);
    if (scwin.result.msgInfomation !== "") {
        await alertE(scwin.result.msgInfomation.replace(/<br\/>/gi, "\n"));
    }
};

/**
 * @method
 * @name checkSafety
 * @description check Safety 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSafety = async function () {
    const r = await scwin.tx_checkSafety();
    try {
        scwin.checkSafety_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldods10010.checkSafety' });
    }
    return r;
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};
